<section class="panel"><div class="section-label"><span>02</span> Meter & waktu kerja</div><div class="row g-3"><div class="col-md-6"><label class="form-label" for="meter-start"><span class="meter-label">Meter</span> awal</label><input id="meter-start" name="meter_start" type="number" min="0" step="0.01" class="form-control" required value="{{ old('meter_start',$report->meter_start) }}"></div><div class="col-md-6"><label class="form-label" for="meter-end"><span class="meter-label">Meter</span> akhir</label><input id="meter-end" name="meter_end" type="number" min="0" step="0.01" class="form-control" required value="{{ old('meter_end',$report->meter_end) }}"></div><div class="col-md-6"><label class="form-label" for="work-start">Mulai kerja</label><input id="work-start" name="work_start_at" type="datetime-local" class="form-control" required value="{{ old('work_start_at',$report->exists?$report->work_start_at->format('Y-m-d\TH:i'):now()->format('Y-m-d').'T07:00') }}"></div><div class="col-md-6"><label class="form-label" for="work-end">Selesai kerja</label><input id="work-end" name="work_end_at" type="datetime-local" class="form-control" required value="{{ old('work_end_at',$report->exists?$report->work_end_at->format('Y-m-d\TH:i'):now()->format('Y-m-d').'T16:00') }}"></div>@can('daily-report.override-meter')<div class="col-12"><label class="form-label" for="meter_override_reason">Alasan override meter (jika berbeda dari laporan approved terakhir)</label><input id="meter_override_reason" name="meter_override_reason" class="form-control" value="{{ old('meter_override_reason',$report->meter_override_reason) }}"></div>@endcan</div><p class="small-note mt-3 mb-0">Untuk kerja melewati tengah malam, isi tanggal selesai pada hari berikutnya. Maksimal 24 jam.</p></section>
<section class="panel"><div class="section-label"><span>03</span> Lokasi & hasil pekerjaan</div><div class="mb-3"><label class="form-label" for="location_id">Lokasi / blok</label><select name="location_id" class="form-select" required id="location_id">@foreach($locations as $l)<option data-plant="{{ $l->plant_id }}" value="{{ $l->id }}" {{ old('location_id',$report->location_id)==$l->id?'selected':'' }}>{{ $l->code }} · {{ $l->name }} ({{ $l->location_type }})</option>@endforeach</select></div><div id="activity-items">@php($items=old('activities',$report->exists?$report->activities->toArray():[['volume'=>0]])) @foreach($items as $i=>$item)<div class="activity-row"><div class="row g-3"><div class="col-md-5"><label class="form-label" for="activities[{{ $i }}][activity_code_id]">Aktivitas</label><select name="activities[{{ $i }}][activity_code_id]" class="form-select" required id="activities[{{ $i }}][activity_code_id]">@foreach($activities as $a)<option value="{{ $a->id }}" {{ ($item['activity_code_id']??null)==$a->id?'selected':'' }}>{{ $a->code }} · {{ $a->name }}</option>@endforeach</select></div><div class="col-md-3"><label class="form-label" for="activities[{{ $i }}][load_type_id]">Muatan</label><select name="activities[{{ $i }}][load_type_id]" class="form-select" id="activities[{{ $i }}][load_type_id]"><option value="">Tidak ada</option>@foreach($loadTypes as $l)<option value="{{ $l->id }}" {{ ($item['load_type_id']??null)==$l->id?'selected':'' }}>{{ $l->name }}</option>@endforeach</select></div><div class="col-md-2"><label class="form-label" for="activities[{{ $i }}][volume]">Volume</label><input name="activities[{{ $i }}][volume]" type="number" min="0" step="0.01" class="form-control" required value="{{ $item['volume']??0 }}" id="activities[{{ $i }}][volume]"></div><div class="col-md-2"><label class="form-label" for="activities[{{ $i }}][work_unit_id]">Satuan</label><select name="activities[{{ $i }}][work_unit_id]" class="form-select" required id="activities[{{ $i }}][work_unit_id]">@foreach($units as $u)<option value="{{ $u->id }}" {{ ($item['work_unit_id']??null)==$u->id?'selected':'' }}>{{ $u->name }}</option>@endforeach</select></div></div><button type="button" class="btn btn-link text-danger p-0 mt-2" onclick="this.closest('.activity-row').remove()">Hapus baris</button></div>@endforeach</div><button id="add-activity" type="button" class="btn btn-outline-secondary"><x-icon name="plus"/> Tambah aktivitas</button></section>
