</div><div class="col-lg-3"><div class="sticky-summary"><div class="eyebrow text-white">RINGKASAN LAPORAN</div><p class="small">Perhitungan disahkan kembali oleh server.</p><label>Total meter</label><div id="meter-total" class="summary-value">0</div><hr><label>Jam kerja</label><div id="hour-total" class="summary-value">0 jam</div><button class="btn btn-yellow w-100 mt-3">Simpan Draft</button><small id="autosave-status" class="d-block mt-3">Draft formulir disimpan otomatis di browser ini.</small></div></div></div></form><template id="fuel-template">@php($i='INDEX') @php($item=[]) @include('daily-reports.fuel-row')</template>@endsection
@push('scripts')<script>
const form=document.getElementById('daily-form');
const eq=document.getElementById('equipment');
const plant=document.getElementById('report-plant');
const activityTemplate=document.querySelector('.activity-row').cloneNode(true);
const fuelTemplate=document.getElementById('fuel-template').innerHTML;
let ai={{ count($items) }},fi={{ count($fuelItems) }};
function appendActivity(index){const row=activityTemplate.cloneNode(true);row.querySelectorAll('[name]').forEach(e=>{e.name=e.name.replace(/activities\[\d+\]/,'activities['+index+']');e.id=e.name;const label=e.closest('[class*=col-]')?.querySelector('label');if(label)label.htmlFor=e.id;if(e.tagName==='INPUT')e.value=0});document.getElementById('activity-items').appendChild(row)}
function appendFuel(index){document.getElementById('fuel-items').insertAdjacentHTML('beforeend',fuelTemplate.replaceAll('INDEX',index));filterPlant(false)}
function totals(){const start=document.getElementById('meter-start'),end=document.getElementById('meter-end');document.getElementById('meter-total').textContent=start.value!==''&&end.value!==''?(Number(end.value)-Number(start.value)).toLocaleString('id-ID'):'—';const minutes=(new Date(document.getElementById('work-end').value)-new Date(document.getElementById('work-start').value))/60000;document.getElementById('hour-total').textContent=Number.isFinite(minutes)?(Math.max(0,minutes)/60).toLocaleString('id-ID')+' jam':'—';document.querySelectorAll('.meter-label').forEach(l=>l.textContent=eq.selectedOptions[0]?.dataset.type||'Meter')}
function filterPlant(resetMeter){form.querySelectorAll('select').forEach(select=>{if(select===plant)return;let changed=false;select.querySelectorAll('option[data-plant]').forEach(o=>{o.hidden=o.dataset.plant!==plant.value;o.disabled=o.hidden;if(o.disabled&&o.selected){o.selected=false;changed=true}});if(changed&&!select.multiple){const available=[...select.options].find(o=>!o.disabled);if(available)select.value=available.value}});if(resetMeter){document.getElementById('meter-start').value=eq.selectedOptions[0]?.dataset.meter||'';document.getElementById('meter-end').value=''}totals()}
plant.addEventListener('change',()=>filterPlant(true));
eq.addEventListener('change',()=>{document.getElementById('meter-start').value=eq.selectedOptions[0]?.dataset.meter||'';totals()});
form.elements.assignment_id.addEventListener('change',()=>{const a=form.elements.assignment_id.selectedOptions[0];if(!a?.dataset.equipment)return;eq.value=a.dataset.equipment;form.elements.main_operator_id.value=a.dataset.operator;form.elements.work_start_at.value=a.dataset.start;form.elements.work_end_at.value=a.dataset.end;form.elements.report_date.value=a.dataset.start.slice(0,10);document.getElementById('meter-start').value=eq.selectedOptions[0]?.dataset.meter||'';totals()});
form.addEventListener('input',totals);
document.getElementById('add-activity').onclick=()=>{if(document.querySelectorAll('.activity-row').length<30)appendActivity(ai++)};
document.getElementById('add-fuel').onclick=()=>{if(document.querySelectorAll('.fuel-row').length<20)appendFuel(fi++)};
const key='daily-draft-{{ auth()->id() }}-{{ $report->id??'new' }}';
form.addEventListener('input',()=>{const values=[...new FormData(form)].filter(([k])=>!['_token','_method'].includes(k));try{localStorage.setItem(key,JSON.stringify(values));document.getElementById('autosave-status').textContent='Draft browser tersimpan '+new Date().toLocaleTimeString('id-ID')}catch{document.getElementById('autosave-status').textContent='Penyimpanan browser tidak tersedia. Gunakan Simpan Draft.'}});

function restoreLocalDraft(saved){const values=JSON.parse(saved);const indexes=prefix=>[...new Set(values.map(([n])=>n.match(new RegExp('^'+prefix+'\\[(\\d+)\\]'))?.[1]).filter(Boolean))];const activities=indexes('activities').slice(0,30),fuels=indexes('fuels').slice(0,20);document.getElementById('activity-items').innerHTML='';activities.forEach(i=>appendActivity(i));document.getElementById('fuel-items').innerHTML='';fuels.forEach(i=>appendFuel(i));ai=Math.max(-1,...activities.map(Number))+1;fi=Math.max(-1,...fuels.map(Number))+1;form.querySelectorAll('select[multiple] option').forEach(o=>o.selected=false);values.forEach(([name,value])=>{const e=[...form.elements].find(e=>e.name===name);if(e){if(e.multiple)[...e.options].forEach(o=>{if(o.value===value)o.selected=true});else e.value=value}});filterPlant(false);totals();}
try{const saved=localStorage.getItem(key);if(saved&&!{{ $errors->any()?'true':'false' }}){const banner=document.createElement('div');banner.className='recovery-banner';banner.setAttribute('role','status');const text=document.createElement('div');const title=document.createElement('strong');title.textContent='Draft yang belum dikirim tersedia';const detail=document.createElement('p');detail.textContent='Anda dapat memulihkan isian terakhir dari browser ini.';text.append(title,detail);const actions=document.createElement('div');const restore=document.createElement('button');restore.type='button';restore.className='btn btn-primary';restore.textContent='Pulihkan draft';restore.addEventListener('click',()=>{try{restoreLocalDraft(saved);banner.remove();}catch{detail.textContent='Draft tidak dapat dipulihkan. Lanjutkan dengan formulir baru.'}});const skip=document.createElement('button');skip.type='button';skip.className='btn btn-outline-secondary';skip.textContent='Lanjutkan isian baru';skip.addEventListener('click',()=>banner.remove());actions.append(restore,skip);banner.append(text,actions);form.before(banner);}}catch{document.getElementById('autosave-status').textContent='Penyimpanan draft browser tidak tersedia.'}
filterPlant(false);totals();
</script>@endpush